  'Bachmann 2003': { autores: 'Bachmann, Kolb, Koller, Steurer y ter Riet', titulo: 'Accuracy of Ottawa ankle rules to exclude fractures of the ankle and mid-foot: systematic review', publicacion: 'BMJ 326:417', doi: '10.1136/bmj.326.7386.417', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC149439/', revision: { fecha: '2026-10', resultado: 'Sustituida en la puntuación por Beckenkamp 2017 (tp5 y tp37); queda como contraste y en el razonamiento de tp_t2, cuyas cifras (las del resumen) coinciden. PDF leído entero (2026-10): LR− con efectos aleatorios univariantes (sensibilidad con bootstrap), niños y adultos juntos, incluye los estudios de Stiell (creador de la regla). El 0,21 que usaba tp5 no era «los estudios que aplican las dos reglas juntas», sino el estrato prospectivo aplicado después de 48 h de la tabla 1; la evaluación conjunta con todos los estudios es 0,17 (0,10–0,30) en la tabla 4.' }, nota: 'Revisión sistemática (27 estudios, 15 581 pacientes). LR− agrupadas del resumen (PubMed, 2026-10): 0,08 para el tobillo y para el mediopié, 0,07 en niños; reduce un 30–40 % las radiografías. Regla de Ottawa en tp5 y razonamiento del cribado de tobillo y pie (tp_t2); autores y PMC149439 comprobados en PubMed.' },
  'Bachmann 2004': { autores: 'Bachmann, Haberzeth, Steurer y ter Riet', titulo: 'The accuracy of the Ottawa knee rule to rule out knee fractures: a systematic review', publicacion: 'Ann Intern Med 140(2):121–4', doi: '10.7326/0003-4819-140-5-200403020-00013', url: 'https://doi.org/10.7326/0003-4819-140-5-200403020-00013', revision: { fecha: '2026-10', resultado: 'Hay dos revisiones sistemáticas posteriores: Sims 2020 (LR− 0,07) y Kazemi 2023 (18 estudios, 6702 adultos; LR− 0,12). Por la regla de conflictos (mismo nivel, la más reciente), Kazemi 2023 pasa a dar las cifras de ro11 y de ro_t1; Bachmann se cita como concordante.' }, nota: 'Revisión sistemática (6 estudios, 4249 adultos): S 98,5 %, E 48,6 %, LR− 0,05, leídas en el resumen de PubMed (2026-10); no está en PMC. Sustituía a la S 1,0 que Lluch 2020 (cap. 4.2, p. 197) toma del estudio de derivación (Stiell 1995). Regla de Ottawa en ro11 y razonamiento de ro_t1, ahora como revisión concordante con Kazemi 2023.' },
  'Balcarek 2025': { autores: 'Balcarek, Blønd, Beaufils, Askenberger, Stephen y cols.', titulo: 'Management of first-time patellar dislocation: The ESSKA 2024 formal consensus—Part 2', publicacion: 'Knee Surg Sports Traumatol Arthrosc 33(12):4197–4206', doi: '10.1002/ksa.12637', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12684363/', revision: { fecha: '2026-10', resultado: 'Sin cambios: PubMed (consensos y guías de primera luxación de rótula desde 2024) no encuentra nada posterior; el consenso de 2024 para adolescentes (J Pediatr Orthop) es anterior.' }, nota: 'Consenso formal ESSKA; texto completo leído en PMC12684363 (2026-10). Pauta de ro12.' },
  'Barcelos 2014': { autores: 'Barcelos, Patriota y Netto', titulo: 'Nontraumatic atlantoaxial rotatory subluxation: Grisel syndrome. Case report and literature review', publicacion: 'Global Spine J 4(3):179–186', doi: '10.1055/s-0033-1363936', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4111947/', revision: { fecha: '2026-10', resultado: 'Sin cambios: búsqueda en PubMed (2026-10). Lo posterior son casos clínicos y revisiones de casos (leídos los resúmenes): Heck 2026 (Int J Pediatr Otorhinolaryngol, revisión sistemática de 13 casos de luxación occipito-atloaxoidea por Grisel diagnosticado tarde; media de 5,9 meses hasta el diagnóstico), Cirrincione 2026 (Curr Opin Pediatr, revisión narrativa: con diagnóstico precoz basta tratamiento no quirúrgico) y Koru 2025 (Clin Rheumatol, Grisel sin infección en enfermedades reumáticas). Coinciden con el razonamiento de la pregunta (derivar pronto, el retraso empeora el tratamiento); no lo cambian.' }, nota: 'Texto completo en PMC4111947 (acceso abierto). Caso clínico y revisión; razonamiento del cribado cervical (cv_n3).' },
  'Barney 2023': { autores: 'Barney, Piuzzi y Akhondi', titulo: 'Femoral Head Avascular Necrosis', publicacion: 'StatPearls [Internet], NBK546658 (act. 2023-07-03)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK546658/', revision: { fecha: '2026-10', resultado: 'Sin cambios: el capítulo de StatPearls no se ha actualizado desde el 3 de julio de 2023 (fecha del documento en PubMed, consultada en 2026-10).' }, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo. Razonamiento del cribado de cadera.' },
  'Bateman 2025': { autores: 'Bateman, Swaile y Tambe', titulo: 'Effectiveness of night splints for cubital tunnel syndrome - A systematic review', publicacion: 'Hand Ther 30(3):105–112', doi: '10.1177/17589983251336157', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12081431/', revision: null, nota: 'Revisión sistemática (RoB 2, ROBINS-I y GRADE). Solo el resumen de los autores (Europe PMC no da el texto completo). Leído en la sesión de dosis de codo (2026-10). Pauta de co8: evidencia insuficiente sobre la férula nocturna (certeza muy baja). Más reciente que Natroshvili 2023 (mismo nivel), que no se cita.' },
  'Basit 2023': { autores: 'Basit, Pop, Malik y Sharma', titulo: 'Fitz-Hugh-Curtis Syndrome', publicacion: 'StatPearls [Internet], NBK499950 (act. 2023-07-03)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK499950/', revision: { fecha: '2026-10', resultado: 'Sin cambios: el capítulo de StatPearls no se ha actualizado desde el 3 de julio de 2023 (fecha del documento en PubMed, consultada en 2026-10).' }, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo. Razonamiento del cribado de hombro.' },
  'Beckenkamp 2017': { autores: 'Beckenkamp, Lin, Macaskill, Michaleff, Maher y Moseley', titulo: 'Diagnostic accuracy of the Ottawa Ankle and Midfoot Rules: a systematic review with meta-analysis', publicacion: 'Br J Sports Med 51(6):504–10', doi: '10.1136/bjsports-2016-096858', revision: { fecha: '2026-10', resultado: 'Añadida (PDF del usuario, leído entero): 66 estudios, modelo bivariante. Sustituye a Bachmann 2003 en la LR− de tp5 y tp37 (subgrupo con radiografía a todos los pacientes) y a Gomes 2022 en la LR+ del positivo. PubMed (2026-10): Sharifi Razavi 2026 (Arch Acad Emerg Med; 43 estudios en adultos, LR− 0,13) es posterior, pero copia errores de extracción de Gomes 2022 y mezcla tobillo y pie: no se usa.' }, nota: 'Publicada en línea en 2016. Incluye los estudios de Stiell (creador de la regla) y 8 resúmenes de congreso. Tabla 1: regla del tobillo LR− 0,018 (34 estudios), 0,030 con radiografía a todos (25); reglas de tobillo y pie juntas 0,090 (31), 0,082 con radiografía a todos (22).' },
