  'Biz 2019': { autores: 'Biz, Crimì, Belluzzi, Maschio, Baracco, Volpin y Ruggieri', titulo: 'Conservative Versus Surgical Management of Elbow Medial Ulnar Collateral Ligament Injury: A Systematic Review', publicacion: 'Orthop Surg 11(6):974–984', doi: '10.1111/os.12571', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6904592/', revision: null, nota: 'Revisión sistemática de 15 estudios, casi todos de nivel IV; texto completo leído en Europe PMC. Leído en la sesión de dosis de codo (2026-10). Pauta de co4.' },
  'Blanpied 2017': { publicacion: 'J Orthop Sports Phys Ther 47(7):A1–A83', doi: '10.2519/jospt.2017.0302', revision: { fecha: '2026-10', resultado: 'Sin cambios: PDF del usuario leído (2026-10): resumen de recomendaciones (A2–A3), pronóstico (A13–A14, tabla 6), mielopatía (A15), medidas de exploración (A19–A20), modelo de clasificación (A22) e intervenciones (tablas 7–10, A26–A42); las pautas y las letras de ce1–ce7, ce9, ce11, ce12 y ce14 y las páginas citadas coinciden. Matiz añadido a ce11: el programa en casa de resistencia de flexores (1 año, 3 veces por semana) aparece como beneficio frente al aeróbico (A29) y, con el mismo estudio, como sin beneficio frente a aeróbico más estiramientos (A30). No hay revisión posterior de la guía APTA (PubMed, JOSPT, 2026-10); la guía alemana S3 de dolor cervical inespecífico (El-Allawy 2025) no cambia las pautas.' } },
