  'Kastelein 2008': { publicacion: 'Am J Med', doi: '10.1016/j.amjmed.2008.05.041', revision: { fecha: '2026-10', resultado: 'Sin cambios: PDF del usuario leído; S 0,56, E 0,91, LR+ 6,4 (2,7–15,2) y LR− 0,5 (0,3–0,8) de la combinación coinciden con la tabla 5 (un solo fisioterapeuta exploró a todos los pacientes). PubMed (exploración clínica del LCM de rodilla, revisiones sistemáticas desde 2008) no encuentra ningún estudio ni revisión posterior de precisión diagnóstica de la exploración.' } },
  'Katz 1995': { publicacion: '', doi: '10.1002/art.1780380910', revision: { fecha: '2026-10', resultado: 'Sin cambios: sus datos (Romberg y dolor de muslo con 30 s de extensión) están en Cook 2019 (PDF del usuario), con riesgo de sesgo bajo y las mismas cifras; los dos tests de lu4 pasan a citar Cook 2019. Su patrón de referencia es el diagnóstico del médico experto, no la RM: se corrige en la cita.' }, nota: 'Citado a través de Dobbs 2016.' },
  'Kaur 2025': { autores: 'Kaur, Gandhi y Sharma', titulo: 'Physiology, Cortisol', publicacion: 'StatPearls [Internet], NBK538239 (act. 2025-12-01)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK538239/', revision: null, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo.' },
  'Kazemi 2023': { autores: 'Kazemi, Khorram, Fayyazishishavan y cols.', titulo: 'Diagnostic Accuracy of Ottawa Knee Rule for Diagnosis of Fracture in Patients with Knee Trauma; a Systematic Review and Meta-analysis', publicacion: 'Arch Acad Emerg Med 11(1):e30', doi: '10.22037/aaem.v11i1.1934', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10197917/', revision: { fecha: '2026-10', resultado: 'Sin cambios: texto completo leído en PMC; S 98 %, E 43 %, LR+ 1,56 y LR− 0,12 (0,05–0,26) coinciden. Agrupa con un modelo univariante (Meta-DiSc, DerSimonian-Laird), y Sims 2020 es bivariante; se mantiene por decisión del usuario (más estudios y LR− más conservadora) y se anota el modelo en la cita. PubMed (revisiones de la regla de Ottawa de rodilla desde 2020) no encuentra ninguna posterior.' }, nota: 'Revisión sistemática más reciente de la regla de Ottawa de rodilla (18 estudios, 6702 adultos; S 98 %, E 43 %, LR+ 1,56, LR− 0,12); texto completo leído en PMC (2026-10). Sustituye a Bachmann 2004 en ro11 (puntúa con LR− 0,12) y en el razonamiento de ro_t1, por la regla de conflictos (mismo nivel, la más reciente).' },
  'Kelley 2013': { autores: 'Kelley, Shaffer, Kuhn, Michener, Seitz, Uhl, Godges y McClure', titulo: 'Shoulder Pain and Mobility Deficits: Adhesive Capsulitis. Clinical Practice Guidelines', publicacion: 'J Orthop Sports Phys Ther 43(5):A1–A31', doi: '10.2519/jospt.2013.0302', revision: { fecha: '2026-10', resultado: 'Sin cambios: búsqueda en PubMed (2026-10) sin revisión de la guía de capsulitis adhesiva de JOSPT; sigue vigente junto con el consenso Salamh 2025.' }, nota: 'PDF aportado por el usuario. Guía APTA de capsulitis adhesiva (Lluch 2020, cap. 3.1.1, ref. 23). Pauta de h1 y test de rotación externa de h1. Donde choca con Salamh 2025 (consenso de expertos, posterior pero de menor nivel) se presentan las dos.' },
  'Kemp 2026': { autores: 'Kemp, Scholes, Smith, Coburn, Johnston, Jones, Girdwood, King, Mentiplay, De Oliveira Silva, Pazzinatto, Schache, Gomes, Coburn y Crossley', titulo: 'Physiotherapist-led treatment for femoroacetabular impingement syndrome (the PhysioFIRST study): an assessor-blinded, limited disclosure randomised controlled trial', publicacion: 'Br J Sports Med 60(13):951–961', doi: '10.1136/bjsports-2025-110986', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC13479264/', revision: { fecha: '2026-10', resultado: 'Ensayo más reciente sobre fisioterapia en el SIFA (PubMed, 2026-10); se suma a la pauta de ca2.' }, nota: 'Texto completo en PMC13479264 (leído en 2026-10); DOI comprobado en Crossref. 154 participantes de 18 a 50 años con SIFA (dolor ≥6 semanas, FADIR positivo, morfología cam en la radiografía, Kellgren-Lawrence <2), en 4 clínicas de Victoria (Australia). Fortalecimiento dirigido frente a estiramientos estandarizados, 6 meses: sin diferencia en iHOT-33 (0,2; IC −5,9 a 6,3), los dos mejoran unos 20 puntos; mejoría del dolor percibido 72 % frente a 52 %. Dosis de ca2 (cadera).' },
  'Kemp 2020': { autores: 'Kemp, Mosler, Hart, Bizzini, Chang, Scholes, Semciw y Crossley', titulo: 'Improving function in people with hip-related pain: a systematic review and meta-analysis of physiotherapist-led interventions for hip-related pain', publicacion: 'Br J Sports Med 54(23):1382–1394', doi: '10.1136/bjsports-2019-101690', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7677471/', revision: { fecha: '2026-10', resultado: 'Sin cambios: PubMed (dolor de cadera relacionado con la articulación y fisioterapia, revisiones sistemáticas desde 2021) no encuentra una revisión posterior de las intervenciones; el ensayo PhysioFIRST (Kemp 2026), posterior, se suma a la pauta de ca2.' }, nota: 'Texto completo en PMC7677471. Dosis de ca2 y ca3 (cadera). No confundir con el consenso de Zúrich del mismo grupo y año (entrada «Consenso de Zúrich IHiPRN»).' },
  'Khalil 2025': { autores: 'Khalil, Marwaha y Bollu', titulo: 'Physiology, Neuromuscular Junction', publicacion: 'StatPearls [Internet], NBK470413 (act. 2025-02-17)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK470413/', revision: null, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo. Razonamiento del cribado de codo.' },
