  'Logerstedt 2018': { autores: 'Logerstedt, Scalzitti, Bennell, Hinman, Silvers-Granelli, Ebert, Hambly, Carey, Snyder-Mackler, Axe y McDonough', titulo: 'Knee Pain and Mobility Impairments: Meniscal and Articular Cartilage Lesions Revision 2018', publicacion: 'J Orthop Sports Phys Ther 48(2):A1–A50', doi: '10.2519/jospt.2018.0301', url: 'https://www.orthopt.org/content/s/knee-pain-and-mobility-impairments-meniscal-and-articular-cartilage-lesions-2018', revision: { fecha: '2026-10', resultado: 'Complementada: el consenso formal EU-US de 2024 (Prill 2025, acceso abierto) cubre el tratamiento sin cirugía, que la guía deja para su próxima revisión; la pauta de ro2 suma sus recomendaciones con su grado. La guía AAOS 2024 de patología meniscal aislada aguda (PDF completo del usuario) también se suma a la pauta de ro2 (opciones de consenso).' }, nota: 'Guía de práctica clínica APTA; PDF completo de orthopt.org leído (resumen de recomendaciones y ejercicio terapéutico, 2026-10). Pauta de ro2.' },
  'Lopes 2025': { autores: 'Lopes, Rizzo, Hespanhol, Costa y Kamper', titulo: 'Exercise for patellar tendinopathy', publicacion: 'Cochrane Database Syst Rev 5(5):CD013078', doi: '10.1002/14651858.CD013078.pub2', url: 'https://doi.org/10.1002/14651858.CD013078.pub2', revision: { fecha: '2026-10', resultado: 'Sin cambios: es la revisión Cochrane más reciente; el metaanálisis en red posterior (BMC Sports Sci Med Rehabil, 2026) no la sustituye en la pauta, que sigue la guía holandesa (Ophey 2025).' }, nota: 'Revisión Cochrane (7 ensayos, 211 deportistas); leído el resumen de PubMed (2026-10). Matiz de la pauta de ro5.' },
