  'Maffulli 1998': { publicacion: 'Am J Sports Med 26:266–70', doi: '10.1177/03635465980260021801', revision: { fecha: '2026-10', resultado: 'Sin cambios en las cifras: PDF leído entero (2026-10). Tabla 1: Thompson positivo en 128 de 133 roturas operadas (S 96 %), hueco palpable con el paciente despierto en 97 de 133 (S 73 %); tabla 3: 26 de 28 controles sin rotura (los 2 dudosos contados como falsos positivos). Diseño de casos y controles (casos por diagnóstico clínico; controles descartados clínicamente por el autor antes de la ecografía o la RM): se añade como límite en tp3, que sigue puntuando (decisión del usuario). PubMed (2026-10): ninguna revisión posterior de la exploración clínica de la rotura del Aquiles.' } },
  'Mahadevan 2015': { publicacion: 'J Foot Ankle Surg 54:549–53', doi: '10.1053/j.jfas.2014.09.021', revision: { fecha: '2026-10', resultado: 'Sin cambios: PDF leído entero (2026-10): 54 pies en 40 pacientes; compresión pulgar-índice positiva en 51 de 53 pies con Morton y 1 verdadero negativo (el único pie sin Morton). Solo incluyó pies con algún test clínico positivo.' } },
  'Majlesi 2008': { publicacion: '', doi: '10.1097/rhu.0b013e31816b2f99', revision: { fecha: '2026-10', resultado: 'Cifras sin cambios, con aviso: van der Windt 2010 (Cochrane) recoge solo dos estudios del Slump y señala que la especificidad de Majlesi puede estar inflada por su diseño de casos y controles (controles con RM normal); el otro estudio dio S 0,44, E 0,58. PubMed (2026-10): ninguna revisión posterior del Slump. Por decisión del usuario (2026-10), el Slump pasa a hallazgo: sus cifras quedan en el criterio y no puntúa.' } },
