  'Martin 2021': { publicacion: 'J Orthop Sports Phys Ther 51(4):CPG1–CPG80', doi: '10.2519/jospt.2021.0302', revision: { fecha: '2026-10', resultado: 'Sin cambios de fondo: PDF leído entero (2026-10); las letras citadas coinciden. Se matizan en tp1 la inmovilización («puede estar indicada») y la terapia manual (con sus objetivos), y se añade la vuelta al trabajo o al deporte (B); en tp21, la tobillera o el vendaje no como tratamiento único para mejorar el equilibrio (B), pero sí para prevenir la recidiva. Es la revisión de 2021 (revisión prevista en 2025); PubMed (2026-10): sin versión posterior de la APTA.' } },
  'Mastromarchi 2021': { autores: 'Mastromarchi y May', titulo: 'First rib dysfunction in patients with neck and shoulder pain: a Delphi investigation', publicacion: 'J Man Manip Ther 29(3):181–188', doi: '10.1080/10669817.2020.1824470', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8183555/', revision: { fecha: '2026-10', resultado: 'Sin cambios: búsqueda en PubMed (2026-10) sin estudios posteriores de fiabilidad ni validez de los tests de la 1.ª costilla. Sigue como opinión de expertos; no puntúa (h9 y ce10).' }, nota: 'PDF aportado por el usuario. Delphi de 12 expertos en terapia manual (cuatro rondas): opinión de expertos; los autores piden estudiar la fiabilidad y la validez de los tests. Tests de la 1.ª costilla de h9 y ce10.' },
  'Maxwell y Sterling 2013': { publicacion: 'Man Ther 18:172–174', doi: '10.1016/j.math.2012.07.004', revision: { fecha: '2026-10', resultado: 'Sin cambios: PDF del usuario leído entero (2026-10). Tabla 1: dolor con el hielo más de 5/10 → S 42 %, E 95 %, LR+ 8,44 (6,3–11,3), LR− 0,61; más de 1/10 → LR− 0,18. 62 participantes con latigazo crónico (voluntarios de estudios previos), 124 lados del cuello; referencia: umbral de dolor al frío ≥13 °C; orden de los tests no aleatorizado. Coincide con ce5 (tipo pronóstico, no puntúa). PubMed (2026-10): ningún estudio posterior de precisión del test del hielo.' } },
  'May y Marappa-Ganeshan 2023': { autores: 'May y Marappa-Ganeshan', titulo: 'Stress Fractures', publicacion: 'StatPearls [Internet], NBK554538 (act. 2023-07-10)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK554538/', revision: { fecha: '2026-10', resultado: 'Sin cambios: el capítulo de StatPearls no se ha actualizado desde el 10 de julio de 2023 (fecha del documento en PubMed, consultada en 2026-10).' }, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo. Releído en la sesión de tobillo y pie (2026-10): razonamiento del cribado de tobillo y pie.' },
