  'Salamh 2025': { autores: 'Salamh, Stoner, Ruley, Zhu, Bateman, Chester, Da Baets, Gibson, Hollmann, Kelley, Lewis, McClure, McCreesh, Mertens, Michener, Seitz, Struyf, Zuckerman y King', titulo: 'An international consensus on the etiology, risk factors, diagnosis and Management for individuals with Frozen Shoulder: a Delphi study', publicacion: 'J Man Manip Ther 33(4):309–320', doi: '10.1080/10669817.2025.2470461', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12281644/', revision: { fecha: '2026-10', resultado: 'Sin cambios: consenso de 2025; búsqueda en PubMed (2026-10) sin guía ni consenso posterior sobre el hombro congelado.' }, nota: 'PDF aportado por el usuario. Consenso Delphi de 14 expertos (12 fisioterapeutas): opinión de expertos, no evidencia de eficacia. Pauta de h1 y test de rotación externa de h1.' },
  'Sanchez-Alvarado 2024': { autores: 'Sanchez-Alvarado, Bokil, Cassel y Engel', titulo: 'Effects of conservative treatment strategies for iliotibial band syndrome on pain and function in runners: a systematic review', publicacion: 'Front Sports Act Living 6:1386456', doi: '10.3389/fspor.2024.1386456', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11377285/', revision: { fecha: '2026-10', resultado: 'Sin cambios: hay una revisión posterior, Ferrero 2026 (Orthop Res Rev, 24 estudios, resumen leído), que concluye que la rehabilitación estructurada es la primera opción y que ningún tratamiento puede recomendarse sobre otro por la heterogeneidad; no contradice la pauta de ro6.' }, nota: 'Revisión sistemática; texto completo leído en PMC (2026-10). Pauta de ro6.' },
