  'Sims 2020': { autores: 'Sims, Chau y Davies', titulo: 'Diagnostic accuracy of the Ottawa Knee Rule in adult acute knee injuries: a systematic review and meta-analysis', publicacion: 'Eur Radiol 30(8):4438–46', doi: '10.1007/s00330-020-06804-x', url: 'https://doi.org/10.1007/s00330-020-06804-x', revision: { fecha: '2026-10', resultado: 'Sin cambios: PDF del usuario leído entero (antes solo el resumen); S 0,99, E 0,49, LR+ 1,86 y LR− 0,07 (0,02–0,24), 8 estudios y 7385 adultos, con modelo bivariante. Sigue citada como concordante con Kazemi 2023 (decisión del usuario).' }, nota: 'Revisión sistemática (8 estudios, 7385 adultos; S 99 %, E 49 %, LR− 0,07); leído el resumen de PubMed (2026-10). Concordante con Kazemi 2023 en ro11 y ro_t1.' },
  'Singleton y Hefner 2023': { autores: 'Singleton y Hefner', titulo: 'Spinal Cord Compression', publicacion: 'StatPearls [Internet], NBK557604 (act. 2023-02-13)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK557604/', revision: { fecha: '2026-10', resultado: 'Sin cambios: el capítulo de StatPearls no se ha actualizado desde el 13 de febrero de 2023 (fecha del documento en PubMed, consultada en 2026-10).' }, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo.' },
  'Sleijser-Koehorst 2021': { autores: 'Sleijser-Koehorst, Coppieters, Epping, Rooker, Verhagen y Scholten-Peeters', titulo: 'Diagnostic accuracy of patient interview items and clinical tests for cervical radiculopathy', publicacion: 'Physiotherapy 111:74–82', doi: '10.1016/j.physio.2020.07.007', revision: { fecha: '2026-10', resultado: 'Añadida: PDF del usuario leído entero (2026-10). 134 pacientes consecutivos con sospecha de radiculopatía, clínica de un neurocirujano más RM. Tabla 4: SART S 0,50, E 0,75, LR+ 1,88 (1,22–2,91), LR− 0,64 (N = 131); ULNT1 S 0,67, E 0,67, LR+ 1,95, LR− 0,48 (N = 130); Spurling S 0,59, E 0,84, LR+ 3,46, LR− 0,47. Estudio de riesgo bajo de Thoomes 2026; con él la SART pasa a hallazgo.' } },
  'Sman 2015': { publicacion: 'Br J Sports Med', doi: '10.1136/bjsports-2013-092787', revision: { fecha: '2026-10', resultado: 'Sin cambios: PDF leído entero (2026-10): 87 pacientes, 38 con lesión de la sindesmosis, RM de referencia leída a ciegas; la tabla 3 cuadra (squeeze 10/6/28/43; dolor a la palpación de los ligamentos de la sindesmosis S 0,92, E 0,29, LR− 0,28).' } },
  'Smidt y Massey 2023': { autores: 'Smidt y Massey', titulo: '5th Metatarsal Fracture', publicacion: 'StatPearls [Internet], NBK544369 (act. 2023-05-29)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK544369/', revision: { fecha: '2026-10', resultado: 'Sin cambios: el capítulo sigue en su versión del 29 de mayo de 2023 (fecha del documento en PubMed, consultada en 2026-10).' }, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo. Razonamiento del cribado de tobillo y pie.' },
  'Smith 2015': { publicacion: 'Evid Based Med 20:88–97', doi: '10.1136/ebmed-2014-110160', revision: { fecha: '2026-10', resultado: 'Cifras actualizadas en ro2 (PDF del usuario, tabla 3): el metaanálisis es bivariante y publica LR, que antes no se usaban (se calculaban desde S y E): McMurray LR+ 3,2, LR− 0,52; interlínea LR+ 4,0, LR− 0,23. Con ellas el McMurray negativo deja de puntuar. Thessaly a 20° (S 75 %, E 87 %, I² 94 %) añadido como hallazgo. PubMed (metaanálisis de McMurray, interlínea y Thessaly desde 2015) no encuentra ninguno posterior; Rana 2026 solo agrupa la exploración compuesta.' } },
  'Sokal 2022': { autores: 'Sokal, Norris, Maddox y Oldershaw', titulo: 'The diagnostic accuracy of clinical tests for anterior cruciate ligament tears are comparable but the Lachman test has been previously overestimated: a systematic review and meta-analysis', publicacion: 'Knee Surg Sports Traumatol Arthrosc 30(10):3287–3303', doi: '10.1007/s00167-022-06898-4', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9464183/', revision: { fecha: '2026-10', resultado: 'Sin cambios: texto completo leído en PMC; las cifras de la tabla 4 (modelo bivariante) coinciden en los cuatro tests de ro4. Hay dos metaanálisis posteriores solo del Lever: Hesmerg 2024 (23 estudios, sin el del creador; S 79 %, E 92 %, LR+ 9,9, LR− 0,22; agrupación univariante de S y E) concuerda, y Hu 2024 (12 estudios, con el del creador) da E 78 %. Se citan en el criterio; por el método (bivariante, LCA sin otras lesiones ligamentosas) sigue mandando Sokal.' }, nota: 'Revisión sistemática con metaanálisis bivariante; texto completo leído en PMC (2026-10), cifras de la tabla 4. Lachman, cajón anterior, pivot shift y Lever de ro4 (puntúan con sus LR publicadas). Huang 2022 (Medicine, agosto de 2022, univariante) es del mismo año: se elige Sokal por el método, que tiene en cuenta la correlación entre S y E.' },
  'Solomon 2001': { publicacion: 'JAMA 286:1610–20', doi: '10.1001/jama.286.13.1610', revision: { fecha: '2026-10', resultado: 'Sin cambios: PDF del usuario leído; combinación LR+ 2,7 (1,4–5,1), LR− 0,4 (0,2–0,7), McMurray 1,3 / 0,8 e interlínea 0,9 / 1,1 coinciden con el resumen y la tabla 5. Hay una revisión posterior de la exploración compuesta, Rana 2026 (S 85 %, E 95 % en el menisco medial, sin LR): por decisión del usuario sigue mandando Solomon y Rana se cita en el criterio.' } },
