  'Trager 2024': { autores: 'Trager, Baumann, Rogers, Tidd, Orellana, Preston y Baldwin', titulo: 'Efficacy of manual therapy for sacroiliac joint pain syndrome: a systematic review and meta-analysis of randomized controlled trials', publicacion: 'J Man Manip Ther 32(6):561–572', doi: '10.1080/10669817.2024.2316420', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11578406/', revision: { fecha: '2026-10', resultado: 'Sin cambios: es la revisión más reciente que encontró la búsqueda en PubMed (terapia manual en el dolor sacroilíaco) al incorporarla en 2026-10.' }, nota: 'PDF del usuario (2026-10), leído entero. Pauta de lu8.' },
