  'Uysal 2015': { autores: 'Uysal, Akbal, Gökmen, Adam y Reşorlu', titulo: 'Prevalence of pes anserine bursitis in symptomatic osteoarthritis patients: an ultrasonographic prospective study', publicacion: 'Clin Rheumatol 34(3):529–33', doi: '10.1007/s10067-014-2653-8', url: 'https://doi.org/10.1007/s10067-014-2653-8', revision: { fecha: '2026-10', resultado: 'Sin cambios: PubMed (bursitis de la pata de ganso desde 2015) no encuentra ninguna cifra de prevalencia posterior en artrosis.' }, nota: 'Leído el resumen de PubMed (2026-10); publicado en línea en 2014. Prevalencia del 20 % en ro7 (la que cita Lluch 2020).' },
  'Vadakekut y Gnugnoli 2025': { autores: 'Vadakekut y Gnugnoli', titulo: 'Ectopic Pregnancy', publicacion: 'StatPearls [Internet], NBK539860 (act. 2025-03-27)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK539860/', revision: { fecha: '2026-10', resultado: 'Sin cambios: el capítulo de StatPearls no se ha actualizado desde el 27 de marzo de 2025 (fecha del documento en PubMed, consultada en 2026-10).' }, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo. Razonamiento del cribado de hombro.' },
  'van Dijk 2016': { publicacion: 'Knee Surg Sports Traumatol Arthrosc 24(4):1217–27', doi: '10.1007/s00167-016-4017-1', revision: { fecha: '2026-10', resultado: 'Sin cambios: PDF leído entero (2026-10); las recomendaciones citadas coinciden con su apartado final. Los 143 tobillos son de deportistas profesionales y universitarios (su tabla 1), no solo profesionales: corregido en tp2. PubMed (2026-10): ningún consenso posterior sobre el tratamiento conservador de la lesión aislada.' }, nota: 'Consenso ESSKA-AFAS sobre el tratamiento de la lesión aguda y aislada de la sindesmosis; PDF aportado por el usuario. Leído junto con su compañero de clasificación y diagnóstico (van Dijk et al., KSSTA 2016;24(4):1200–16, doi 10.1007/s00167-015-3942-8), que no se cita.' },
  'van Dijk 1996': { publicacion: 'J Bone Joint Surg Br 78-B(6)', doi: '10.1302/0301-620x.78b6.0780958', revision: { fecha: '2026-10', resultado: 'PDF leído entero (2026-10). La referencia es la cirugía, o el seguimiento a 6 meses en los 25 no operados (no la artrografía); la exploración diferida fue a los 4–7 días; la tabla II da para el cajón solo S 74 % (90 de 122), no el 86 % del texto. Corregido en tp1 (el test no puntúa). DOI corregido: el anterior no existía.' } },
  'van der Windt 2010': { autores: 'van der Windt, Simons, Riphagen, Ammendolia, Verhagen, Laslett, Devillé, Deyo, Bouter, de Vet y Aertgeerts', titulo: 'Physical examination for lumbar radiculopathy due to disc herniation in patients with low-back pain', publicacion: 'Cochrane Database Syst Rev 2010, n.º 2, CD007431', doi: '10.1002/14651858.CD007431.pub2', revision: { fecha: '2026-10', resultado: 'Sin cambios: PubMed (revisiones de la exploración física en ciática o hernia discal desde 2011). Scaia 2012 (J Back Musculoskelet Rehabil, 7 estudios del SLR) no agrupa; Al Nezari 2013 (Spine J) trata la exploración neurológica, no el SLR; Tawa 2017 (BMC Musculoskelet Disord, leída entera en PMC) no hace metaanálisis y da una media del SLR (S 0,84, E 0,78) con patrones de referencia mezclados. La Cochrane, con metaanálisis y referencia quirúrgica, sigue siendo la mejor.' }, nota: 'PDF del usuario (2026-10), leído entero. SLR y SLR cruzado de lu3 (tabla de resultados) y límites del Slump.' },
