  'Verhagen 2017': { autores: 'Verhagen, Downie, Maher y Koes', titulo: 'Most red flags for malignancy in low back pain guidelines lack empirical support: a systematic review', publicacion: 'Pain 158(10):1860–1868', doi: '10.1097/j.pain.0000000000000998', url: 'https://doi.org/10.1097/j.pain.0000000000000998', revision: { fecha: '2026-10', resultado: 'Sin cambios: PubMed (banderas rojas de malignidad en lumbalgia, revisiones desde 2017) solo encuentra Galliker 2020 (urgencias), que se cita junto a ella.' }, nota: 'PDF del usuario (2026-10), leído entero. Preguntas `l2` y `l_on2` (tabla 1).' },
